#!/usr/bin/env python3
"""Make the VCD example files in assets/examples/vcd/.

The files are made by this script (no capture from a device), so they can
be part of the app. Run it again to make the same files:

    python3 scripts/make-vcd-examples.py
"""

import math
import random
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / "assets" / "examples" / "vcd"


def header(timescale, variables):
    """VCD header: `variables` is a list of (kind, width, id, name)."""
    lines = [
        "$date 2026-11-08 $end",
        "$version Generated by FNIRSI-Viewer example script $end",
        f"$timescale {timescale} $end",
        "$scope module top $end",
    ]
    for kind, width, ident, name in variables:
        lines.append(f"$var {kind} {width} {ident} {name} $end")
    lines += ["$upscope $end", "$enddefinitions $end"]
    return lines


class Dump:
    """Value changes, in time order; a value is written only if it changes."""

    def __init__(self):
        self.events = {}  # time -> list of lines
        self.last = {}

    def set(self, t, ident, value, width=1):
        if self.last.get(ident) == value:
            return
        self.last[ident] = value
        if width == 1:
            line = f"{value}{ident}"
        elif isinstance(value, str):
            line = f"b{value} {ident}"  # x / z vectors
        else:
            line = f"b{value:b} {ident}"
        self.events.setdefault(t, []).append(line)

    def real(self, t, ident, value):
        self.events.setdefault(t, []).append(f"r{value:.4f} {ident}")

    def lines(self):
        out = []
        for t in sorted(self.events):
            out.append(f"#{t}")
            out += self.events[t]
        return out


def memory_bus():
    """A small CPU bus: reset, then write and read cycles of 4 clocks each.

    clk 10 MHz (period 100 ns). Each cycle: the address is set on the first
    rising edge, the strobe (wr_n or rd_n) is low for clocks 2 and 3, and the
    data bus is driven only while the strobe is low (else z). A read gets its
    data 30 ns after the strobe (the memory access time); before that the
    data is unknown (x). `beat[2:0]` counts the clocks of each cycle (0-3).
    An empty address reads 0xFF.
    """
    period = 100
    d = Dump()
    # Before reset: everything unknown.
    d.set(0, "#", "x" * 16, 16)
    d.set(0, "$", "z" * 8, 8)
    d.set(0, "%", "x" * 3, 3)
    d.set(0, "\"", 0)  # rst_n
    d.set(0, "&", 1)
    d.set(0, "'", 1)
    memory = {}
    # (write?, address, data): fill a small table, then read it back.
    cycles = [(True, 0x2000 + i, (0x41 + 3 * i) & 0xFF) for i in range(6)]
    cycles += [(False, 0x2000 + i, None) for i in range(6)]
    cycles += [(True, 0x80FF, 0xA5), (False, 0x80FF, None), (False, 0x0004, None)]
    start = 3  # clocks of reset
    total_clocks = start + 4 * len(cycles) + 2
    for k in range(total_clocks):
        t = k * period
        d.set(t, "!", 1)
        d.set(t + period // 2, "!", 0)
    d.set(start * period - 20, "\"", 1)  # reset released
    d.set(start * period, "#", 0, 16)
    for n, (write, addr, data) in enumerate(cycles):
        t0 = (start + 4 * n) * period
        d.set(t0 + 5, "#", addr, 16)
        for beat in range(4):
            d.set(t0 + beat * period + 5, "%", beat, 3)
        strobe = "&" if write else "'"
        d.set(t0 + period + 10, strobe, 0)
        if write:
            memory[addr] = data
            d.set(t0 + period + 15, "$", data, 8)
        else:
            # Unknown until the memory answers; an empty address reads 0xFF.
            d.set(t0 + period + 15, "$", "x" * 8, 8)
            d.set(t0 + period + 40, "$", memory.get(addr, 0xFF), 8)
        d.set(t0 + 3 * period + 10, strobe, 1)
        d.set(t0 + 3 * period + 20, "$", "z" * 8, 8)
    end = total_clocks * period
    d.events.setdefault(end, [])
    variables = [
        ("wire", 1, "!", "clk"),
        ("wire", 1, "\"", "rst_n"),
        ("wire", 1, "&", "wr_n"),
        ("wire", 1, "'", "rd_n"),
        ("wire", 16, "#", "addr [15:0]"),
        ("wire", 8, "$", "data [7:0]"),
        ("reg", 3, "%", "beat [2:0]"),
    ]
    return header("1 ns", variables) + d.lines()


def dac_sine():
    """An 8-bit DAC making a 500 Hz sine: the code, the load strobe and the
    analog output after an RC filter (tau = 40 us), 3.3 V full scale.

    The code changes every 100 us (10 kSa/s); the output is written every
    5 us.
    """
    d = Dump()
    tau = 40.0
    vout = 0.0
    code = 0
    step = 5  # us
    for t in range(0, 6000 + step, step):
        if t % 100 == 0:
            code = round(127.5 + 120 * math.sin(2 * math.pi * 500e-6 * t))
            d.set(t, "!", 1)
        if t % 100 == 10:
            d.set(t, "!", 0)
        d.set(t, "\"", code, 8)
        target = 3.3 * code / 255
        vout += (target - vout) * (1 - math.exp(-step / tau))
        d.real(t, "#", vout)
    variables = [
        ("wire", 1, "!", "load"),
        ("wire", 8, "\"", "code [7:0]"),
        ("real", 64, "#", "vout"),
    ]
    return header("1 us", variables) + d.lines()


def uart_levels(text, bits_per_s, t0_s):
    """(time_s, level) changes of a UART line sending `text` (8N1, idle 1)
    from time `t0_s`."""
    bit = 1.0 / bits_per_s
    t = t0_s
    out = []
    for ch in text.encode():
        levels = [0] + [(ch >> k) & 1 for k in range(8)] + [1]
        for level in levels:
            out.append((t, level))
            t += bit
    return out, t


def uart_at():
    """A host sends "AT\\r\\n" on tx; the device answers "\\r\\nOK\\r\\n"
    on rx 150 us later. 115200 baud, 8N1."""
    d = Dump()
    d.set(0, "!", 1)
    d.set(0, '"', 1)
    tx, end = uart_levels("AT\r\n", 115200, 20e-6)
    rx, end = uart_levels("\r\nOK\r\n", 115200, end + 150e-6)
    for ident, changes in (("!", tx), ('"', rx)):
        for t, level in changes:
            d.set(round(t * 1e9), ident, level)
    d.events.setdefault(round((end + 30e-6) * 1e9), [])
    variables = [("wire", 1, "!", "tx"), ("wire", 1, '"', "rx")]
    return header("1 ns", variables) + d.lines()


def uart_analog():
    """A TTL serial line as an oscilloscope sees it: 3.3 V, 9600 baud,
    8N1, "Hello, FNIRSI!\\r\\n". Edges with a 3 us time constant and
    +-50 mV of noise; one sample every 4 us (26 per bit)."""
    rng = random.Random(1)
    changes, end = uart_levels("Hello, FNIRSI!\r\n", 9600, 300e-6)
    end += 300e-6
    tau, step = 3.0, 4  # us
    d = Dump()
    level, v, k = 1, 3.3, 0
    for t in range(0, round(end * 1e6) + step, step):
        while k < len(changes) and changes[k][0] * 1e6 <= t:
            level = changes[k][1]
            k += 1
        target = 3.3 * level
        v += (target - v) * (1 - math.exp(-step / tau))
        d.real(t, "!", v + rng.uniform(-0.05, 0.05))
    variables = [("real", 64, "!", "tx_pin")]
    return header("1 us", variables) + d.lines()


def uart_frames(data, baud, t0_s, bits=8, parity="N", stop=1, gap_s=0.0, bad_parity=()):
    """(time_s, level) changes of UART frames for the bytes `data`, from
    `t0_s`, with `gap_s` of idle after each frame. `parity` is "N", "E" or
    "O"; the bytes whose index is in `bad_parity` get the wrong parity bit.
    Returns the changes and the end time."""
    bit = 1.0 / baud
    t = t0_s
    out = []
    for n, ch in enumerate(data):
        levels = [0] + [(ch >> k) & 1 for k in range(bits)]
        if parity != "N":
            ones = bin(ch & ((1 << bits) - 1)).count("1")
            p = ones % 2 if parity == "E" else 1 - ones % 2
            if n in bad_parity:
                p = 1 - p
            levels.append(p)
        levels += [1] * stop
        for level in levels:
            out.append((t, level))
            t += bit
        t += gap_s
    return out, t


def nmea(body):
    """An NMEA sentence with its checksum: "$body*hh\\r\\n"."""
    check = 0
    for c in body.encode():
        check ^= c
    return f"${body}*{check:02X}\r\n"


def uart_session():
    """Four serial lines, as a logic analyzer records them (timescale 1 ns):

    - host_tx: a host sends AT commands, 115200 baud, 8N1.
    - dev_tx: the device answers, 115200 8N1. At the end it sends a break
      (the line low for 2 ms): a framing error.
    - gps: a GPS module sends two NMEA sentences, 9600 baud, 8N1.
    - rs232: an RS-232 line before the transceiver (idle low, inverted),
      19200 baud, 7 data bits, even parity, 1 stop bit. One character has a
      wrong parity bit.
    """
    d = Dump()
    for ident in "!\"#":
        d.set(0, ident, 1)
    d.set(0, "$", 0)  # rs232: idle low
    host, dev = [], []
    t = 0.5e-3
    exchanges = [
        ("AT\r\n", "\r\nOK\r\n"),
        ("AT+TEMP?\r\n", "\r\n+TEMP: 23.5 C\r\nOK\r\n"),
        ("AT+NAME=FNIRSI\r\n", "\r\n+NAME: FNIRSI\r\nOK\r\n"),
        ("AT+VER?\r\n", "\r\n+VER: 1.4.2\r\nOK\r\n"),
    ]
    for cmd, answer in exchanges:
        c, t = uart_frames(cmd.encode(), 115200, t, gap_s=2e-6)
        host += c
        a, t = uart_frames(answer.encode(), 115200, t + 400e-6)
        dev += a
        t += 3e-3
    # A break: dev_tx low for 2 ms, then idle again.
    dev += [(t, 0), (t + 2e-3, 1)]
    gps, g_end = uart_frames(
        (
            nmea("GPRMC,123519,A,2526.570,S,04916.512,W,000.5,054.7,081126,,,A")
            + nmea("GPGGA,123519,2526.570,S,04916.512,W,1,08,0.9,920.4,M,0.0,M,,")
        ).encode(),
        9600,
        1.0e-3,
        gap_s=20e-6,
    )
    rs, r_end = uart_frames(
        "ID?\rFNIRSI DPOX180H\r".encode(), 19200, 2.0e-3, bits=7, parity="E", bad_parity=(9,)
    )
    rs = [(t, 1 - level) for t, level in rs]  # inverted line
    end = max(t + 2.5e-3, g_end, r_end) + 1e-3
    for ident, changes in (("!", host), ('"', dev), ("#", gps), ("$", rs)):
        for t, level in changes:
            d.set(round(t * 1e9), ident, level)
    d.events.setdefault(round(end * 1e9), [])
    variables = [
        ("wire", 1, "!", "host_tx"),
        ("wire", 1, '"', "dev_tx"),
        ("wire", 1, "#", "gps"),
        ("wire", 1, "$", "rs232"),
    ]
    return header("1 ns", variables) + d.lines()


def i2c_quarters(transactions):
    """(sda, scl) for each quarter of a clock period, for I2C transactions.

    Each transaction is a list of items: ("start",), ("restart",), ("stop",),
    ("byte", value, ack) or ("idle", quarters). SDA changes only while SCL is
    low, except for start and stop."""
    q = [(1, 1)] * 4
    for tr in transactions:
        for item in tr:
            kind = item[0]
            if kind == "start":
                q += [(1, 1), (0, 1), (0, 0), (0, 0)]
            elif kind == "restart":
                q += [(1, 0), (1, 1), (0, 1), (0, 0)]
            elif kind == "stop":
                q += [(0, 0), (0, 1), (1, 1), (1, 1)]
            elif kind == "byte":
                value, ack = item[1], item[2]
                bits = [(value >> k) & 1 for k in range(7, -1, -1)] + [0 if ack else 1]
                for b in bits:
                    q += [(b, 0), (b, 1), (b, 1), (b, 0)]
            elif kind == "idle":
                q += [(1, 1)] * item[1]
    return q + [(1, 1)] * 4


# A temperature sensor at address 0x48 and an absent device at 0x50.
I2C_SESSION = [
    # Write the configuration register (0x01) with 0x60.
    [("start",), ("byte", 0x48 << 1, True), ("byte", 0x01, True),
     ("byte", 0x60, True), ("stop",), ("idle", 24)],
    # Read the temperature: pointer 0x00, repeated start, read 2 bytes
    # (0x19 0x80 = 25.5 degrees C); the last byte gets a NACK.
    [("start",), ("byte", 0x48 << 1, True), ("byte", 0x00, True),
     ("restart",), ("byte", 0x48 << 1 | 1, True), ("byte", 0x19, True),
     ("byte", 0x80, False), ("stop",), ("idle", 24)],
    # Nobody answers at 0x50: NACK on the address.
    [("start",), ("byte", 0x50 << 1, False), ("stop",)],
]


def i2c_sensor():
    """I2C at 100 kHz (quarter period 2.5 us), as a logic analyzer records
    it: write a register, read the temperature with a repeated start, and an
    address without answer."""
    d = Dump()
    quarter = 2500  # ns
    for k, (sda, scl) in enumerate(i2c_quarters(I2C_SESSION)):
        t = k * quarter
        d.set(t, "!", sda)
        d.set(t, '"', scl)
    d.events.setdefault((k + 1) * quarter, [])
    variables = [("wire", 1, "!", "sda"), ("wire", 1, '"', "scl")]
    return header("1 ns", variables) + d.lines()


def i2c_analog():
    """The temperature read of `i2c_sensor` as an oscilloscope sees it on
    two channels: 3.3 V open-drain lines, slow rising edges (pull-up
    resistor, 1 us), fast falling edges, +-40 mV of noise. One sample every
    0.2 us (50 per clock period)."""
    rng = random.Random(2)
    quarters = i2c_quarters([I2C_SESSION[1]])
    step = 0.2  # us
    quarter = 2.5  # us
    d = Dump()
    v = {"!": 3.3, '"': 3.3}
    n = round(len(quarters) * quarter / step)
    for k in range(n):
        t = k * step
        sda, scl = quarters[min(int(t / quarter), len(quarters) - 1)]
        for ident, level in (("!", sda), ('"', scl)):
            target = 3.3 * level
            tau = 1.0 if target > v[ident] else 0.05
            v[ident] += (target - v[ident]) * (1 - math.exp(-step / tau))
            d.real(round(t * 10), ident, v[ident] + rng.uniform(-0.04, 0.04))
    variables = [("real", 64, "!", "CH1"), ("real", 64, '"', "CH2")]
    return header("100 ns", variables) + d.lines()


def spi_quarters(transactions, idle=8):
    """(cs, sck, mosi, miso) for each quarter of a clock period, SPI mode 0
    (clock idle low, data set while the clock is low, read on the rising
    edge). Each transaction is a list of (mosi byte, miso byte); CS is low
    during a transaction. MISO is high (pulled up) when nobody drives it."""
    q = [(1, 0, 0, 1)] * idle
    for tr in transactions:
        q += [(0, 0, 0, 1)] * 2
        for mosi, miso in tr:
            for k in range(7, -1, -1):
                o, i = (mosi >> k) & 1, (miso >> k) & 1
                q += [(0, 0, o, i), (0, 1, o, i), (0, 1, o, i), (0, 0, o, i)]
        q += [(0, 0, 0, 1)] * 2
        q += [(1, 0, 0, 1)] * idle
    return q


def spi_flash():
    """An SPI flash memory at 1 MHz (quarter period 250 ns), mode 0: read
    the JEDEC ID (0x9F, answer EF 40 18), write enable (0x06), and read 9
    bytes at address 0x000100 (0x03): "Hello SPI"."""
    text = b"Hello SPI"
    session = [
        [(0x9F, 0xFF), (0x00, 0xEF), (0x00, 0x40), (0x00, 0x18)],
        [(0x06, 0xFF)],
        [(0x03, 0xFF), (0x00, 0xFF), (0x01, 0xFF), (0x00, 0xFF)]
        + [(0x00, c) for c in text],
    ]
    d = Dump()
    quarter = 250  # ns
    for k, levels in enumerate(spi_quarters(session)):
        for ident, level in zip("!\"#$", levels):
            d.set(k * quarter, ident, level)
    d.events.setdefault((k + 1) * quarter, [])
    variables = [
        ("wire", 1, "!", "cs"),
        ("wire", 1, '"', "sck"),
        ("wire", 1, "#", "mosi"),
        ("wire", 1, "$", "miso"),
    ]
    return header("1 ns", variables) + d.lines()


def spi_analog():
    """Two channels of an oscilloscope on an SPI bus without CS: CH1 is
    MOSI, CH2 is SCLK. 500 kHz, mode 0, 3.3 V, edges with a 0.1 us time
    constant and +-40 mV of noise; one sample every 0.1 us. The command
    0x9F, a pause, then 0x03 0x00 0x01 0x00."""
    rng = random.Random(3)
    q = spi_quarters([[(0x9F, 0xFF)], [(0x03, 0), (0x00, 0), (0x01, 0), (0x00, 0)]])
    quarter, step, tau = 0.5, 0.1, 0.1  # us
    d = Dump()
    v = {"!": 0.0, '"': 0.0}
    n = round(len(q) * quarter / step)
    for k in range(n):
        t = k * step
        _, sck, mosi, _ = q[min(int(t / quarter), len(q) - 1)]
        for ident, level in (("!", mosi), ('"', sck)):
            v[ident] += (3.3 * level - v[ident]) * (1 - math.exp(-step / tau))
            d.real(k, ident, v[ident] + rng.uniform(-0.04, 0.04))
    variables = [("real", 64, "!", "CH1"), ("real", 64, '"', "CH2")]
    return header("100 ns", variables) + d.lines()


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    files = [
        ("memory-bus.vcd", memory_bus()),
        ("dac-sine.vcd", dac_sine()),
        ("uart-at.vcd", uart_at()),
        ("uart-analog.vcd", uart_analog()),
        ("uart-session.vcd", uart_session()),
        ("i2c-sensor.vcd", i2c_sensor()),
        ("i2c-analog.vcd", i2c_analog()),
        ("spi-flash.vcd", spi_flash()),
        ("spi-analog.vcd", spi_analog()),
    ]
    for name, lines in files:
        (OUT / name).write_text("\n".join(lines) + "\n")
        print(OUT / name)


if __name__ == "__main__":
    main()
